"""Co-op session protocol: session codes, authentication and signed messages (version 1).

Threat model: participants are on the same local or trusted private network; anyone on that
network can see and send packets. Nothing secret travels (only "next Short"-style events), so
messages are authenticated, not encrypted.

* **Session code**: 16 random base32 characters (80 bits) generated by the Host for each
  session, shown as ``ABCD-EFGH-IJKL-MNOP`` and given to the Guest out of band.
* **Handshake** (mutual challenge-response, the code never travels): Guest ``hello`` (name,
  nonce, clock) -> Host ``challenge`` (nonce) -> Guest ``auth`` (HMAC of both nonces and the
  name under the code key) -> Host ``welcome`` (HMAC proving the Host knows the code).
* **Session key**: HMAC(code key, "session" | host nonce | guest nonce); every later message
  carries an HMAC-SHA256 over its canonical JSON and a strictly increasing sequence number,
  so modified, forged and replayed messages are rejected.
* Size limit 2 KB, strict schema, a fixed set of message types and three shared actions.
"""

from __future__ import annotations

import base64
import hashlib
import hmac
import json
import re
import secrets
from dataclasses import dataclass
from typing import Any

PROTOCOL = 1
MAX_MESSAGE_BYTES = 2048
CODE_CHARS = 16
SHARED_ACTIONS = frozenset({"next_short", "previous_short", "toggle_playback"})
"""The only actions a Guest can request. Likes and tab switching are never shared."""
NAME_PATTERN = re.compile(r"^[\w .'-]{1,24}$", re.UNICODE)
_HEX32 = re.compile(r"^[0-9a-f]{32}$")
_HEX64 = re.compile(r"^[0-9a-f]{64}$")
OUTCOMES = frozenset(
    {"succeeded", "no change", "rejected", "failed", "outcome unknown", "not executed"}
)


class CoopProtocolError(ValueError):
    pass


def new_session_code() -> str:
    raw = base64.b32encode(secrets.token_bytes(10)).decode().rstrip("=")
    return "-".join(raw[i : i + 4] for i in range(0, CODE_CHARS, 4))


def normalize_code(code: str) -> str:
    cleaned = re.sub(r"[\s-]", "", code).upper()
    if len(cleaned) != CODE_CHARS or not re.fullmatch(r"[A-Z2-7]+", cleaned):
        raise CoopProtocolError("The session code must be 16 letters and digits (A-Z, 2-7).")
    return cleaned


def code_key(code: str) -> bytes:
    return hashlib.sha256(
        b"interactive-scrolling-coop-v1|" + normalize_code(code).encode()
    ).digest()


def mac(key: bytes, *parts: str) -> str:
    return hmac.new(key, "|".join(parts).encode(), hashlib.sha256).hexdigest()


def session_key(key: bytes, host_nonce: str, guest_nonce: str) -> bytes:
    return hmac.new(key, f"session|{host_nonce}|{guest_nonce}".encode(), hashlib.sha256).digest()


def new_nonce() -> str:
    return secrets.token_hex(16)


def valid_name(name: str) -> str:
    name = name.strip()
    if not NAME_PATTERN.match(name):
        raise CoopProtocolError("Names are 1-24 letters, digits, spaces or . ' -")
    return name


# ---------------------------------------------------------------------- framing


def _canonical(payload: dict[str, Any]) -> bytes:
    return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode()


def sign(key: bytes, payload: dict[str, Any]) -> str:
    body = dict(payload)
    body["mac"] = hmac.new(key, _canonical(payload), hashlib.sha256).hexdigest()
    text = json.dumps(body, separators=(",", ":"))
    if len(text.encode()) > MAX_MESSAGE_BYTES:
        raise CoopProtocolError("message too large")
    return text


def load(raw: str | bytes) -> dict[str, Any]:
    if isinstance(raw, bytes):
        raise CoopProtocolError("binary messages are not accepted")
    if len(raw.encode()) > MAX_MESSAGE_BYTES:
        raise CoopProtocolError("message too large")
    try:
        data = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise CoopProtocolError(f"invalid JSON: {exc.msg}") from exc
    if not isinstance(data, dict) or not isinstance(data.get("type"), str):
        raise CoopProtocolError("message must be an object with a type")
    return data


def verify(key: bytes, data: dict[str, Any]) -> dict[str, Any]:
    """Check the HMAC of a signed message; returns it without the ``mac`` field."""
    received = data.get("mac")
    body = {k: v for k, v in data.items() if k != "mac"}
    if not isinstance(received, str) or not _HEX64.match(received):
        raise CoopProtocolError("missing signature")
    expected = hmac.new(key, _canonical(body), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(received, expected):
        raise CoopProtocolError("invalid signature")
    return body


def require(condition: bool, message: str) -> None:
    if not condition:
        raise CoopProtocolError(message)


def is_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def is_hex32(value: Any) -> bool:
    return isinstance(value, str) and bool(_HEX32.match(value))


def is_hex64(value: Any) -> bool:
    return isinstance(value, str) and bool(_HEX64.match(value))


@dataclass(frozen=True, slots=True)
class SharedAction:
    by: str
    """Participant name."""
    role: str
    """"host" or "guest"."""
    action: str
    outcome: str
    reason: str
    at: float
    """Wall-clock time."""
